{
        ok: false,
        code: "SALES_ERF_REFERENCE_AMBIGUOUS",
        message: `The authoritative Sales source resolves to ${uniqueCandidateIds.length} ERFs.`,
        candidateErfIds: uniqueCandidateIds,
      }

{
      ok: false,
      code: "DRAFT_ERF_REFERENCE_MISMATCH",
